 async function perform(action:string,body:Any,success:string){setBusy(true);try{await api(action,body);notify(success);setModal(null);await refresh();if(view==='teacher'){const next=await query('studio');setStudio(next);if(!selectedClass&&next.classes[0])setSelectedClass(next.classes[0].id);}return true;}catch(e:any){notify(e.message);return false;}finally{setBusy(false);}}
 async function loadAttempt(id:string){setBusy(true);try{const next=await query('attempt',{id});if(next.submitted){const result=await query('report',{id});setReport(result);setReportFilter('All questions');}else{setSession({...next,guest:false});setReport(null);}setModal(null);}catch(e:any){notify(e.message);}finally{setBusy(false);}}
 async function generateModule(config:Any){if(!requireUser('Create an account or sign in to generate questions and save your progress.'))return;setBusy(true);setGenerating(true);setGenerationError('');try{const result=await api('generate',config);await loadAttempt(result.id);if(result.resumed)notify('Your active test has been resumed. Finish it before starting a new quiz.');}catch(e:any){setGenerationError(e.message);notify(e.message);}finally{setBusy(false);setGenerating(false);refresh();}}
 async function beginExam(exam:Any|undefined,practice=false,fresh=true){if(!exam){notify('This test is unavailable.');return;}if(!requireUser('Sign in to take timed tests and save your results.'))return;const moduleId=EXAM_MODULE[exam.id];if(fresh&&moduleId&&exam.id!=='daily-challenge'&&data.generation?.ready){await generateModule({moduleId,count:practice?8:exam.count,difficulty:exam.difficulty??'Standard',language:'en',practice,penalty:practice?0:exam.penalty,minutes:practice?10:exam.minutes});return;}setBusy(true);try{const result=await api('start',{examId:exam.id,practice});await loadAttempt(result.id);if(result.resumed)notify('Your active test has been resumed.');}catch(e:any){notify(e.message);}finally{setBusy(false);}}
 async function downloadWord(){if(!report)return;setBusy(true);try{const response=report.guest?await fetch('/api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({questionIds:report.review.map((q:Any)=>q.id),answers:Object.fromEntries(report.review.filter((q:Any)=>q.chosen!==null).map((q:Any)=>[q.id,q.chosen]))})}):await fetch('/api/review?id='+encodeURIComponent(report.id));if(!response.ok){const e:Any=await response.json();throw new Error(e.error??'Download failed.');}const url=URL.createObjectURL(await response.blob());const anchor=document.createElement('a');anchor.href=url;anchor.download='Porikkhon_Answer_Review.docx';document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);notify('Your Word review is ready.');}catch(e:any){notify(e.message);}finally{setBusy(false);}}
 async function startPractice(subject='Mathematics'){setBusy(true);try{if(data.user){await beginExam({id:subjectExam[subject]},true);}else{const next=await query('practice',{subject});setSession({id:'practice',title:'Daily practice · '+subject,questions:next.questions,answers:{},marked:[],deadline:Date.now()+600000,serverTime:Date.now(),penalty:0,guest:true});setReport(null);setModal(null);}}catch(e:any){notify(e.message);}finally{setBusy(false);}}
 async function openReport(id:string){setBusy(true);try{const r=await query('report',{id});setReport(r);setReportFilter('All questions');window.scrollTo({top:0,behavior:'smooth'});}catch(e:any){notify(e.message);}finally{setBusy(false);}}
 async function bookmarkQuestion(id:string){if(!requireUser('Keep useful questions in your own revision collection.'))return;const next=!data.bookmarks.includes(id);try{await api('bookmark',{questionId:id,saved:next});setData((d:Any)=>({...d,bookmarks:next?[...d.bookmarks,id]:d.bookmarks.filter((q:string)=>q!==id)}));notify(next?'Added to your bookmarks.':'Bookmark removed.');if(view==='bookmarks'&&!next)setSaved(s=>s.filter(q=>q.id!==id));}catch(e:any){notify(e.message);}}
 const historyRows:Any[]=data.history??[];const questionsAnswered=historyRows.reduce((n,a)=>n+a.correct+a.wrong,0),correct=historyRows.reduce((n,a)=>n+a.correct,0),accuracy=questionsAnswered?Math.round(correct/questionsAnswered*100):0,studyMinutes=Math.round(historyRows.reduce((n,a)=>n+a.elapsed,0)/60);const today=dayISO();const todays=historyRows.filter(a=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka'}).format(new Date(a.submitted_at))===today).reduce((n,a)=>n+a.correct+a.wrong,0);const dueTasks=(data.tasks??[]).filter((task:Any)=>task.date===today&&!task.done);const searchResults=initialCatalog.filter(e=>(e.title+' '+e.category+' '+e.subject).toLowerCase().includes(search.toLowerCase())).slice(0,5);const filteredExams=initialCatalog.filter(e=>(track==='All tracks'||e.category===track||e.category==='All tracks')&&(filter==='All tests'||filter==='Free practice'||e.kind==='Live challenge'));
 function ExamCard({exam}:{exam:Exam}){const Icon=icons[exam.subject]??ClipboardList;return <article className="exam-card"><div className="exam-card-top"><span className={'subject-icon '+exam.color}><Icon size={21}/></span><span className={'tag '+(exam.kind==='Live challenge'?'live-tag':'')}>{exam.kind==='Live challenge'?<><span/>LIVE</>:exam.category}</span><button className="icon-button quiet" aria-label={'Details for '+exam.title} onClick={()=>setModal({type:'exam',exam})}><MoreHorizontal size={19}/></button></div><span className="exam-kind">{exam.kind}</span><h3>{exam.title}</h3><p>{exam.description}</p><div className="exam-meta"><span><ClipboardList size={13}/>{exam.count} questions</span><span><Clock size={13}/>{exam.minutes} min</span></div><div className="exam-card-foot"><span className="difficulty"><i className={exam.difficulty.toLowerCase()}/>{exam.difficulty}</span><button onClick={()=>setModal({type:'exam',exam})}>Take test<ArrowUpRight size={15}/></button></div></article>;}
